   108→	private getModelName(pair: RawPair): string {
   109→		// Try to extract from Bedrock URL first
   110→		if (pair.request.url && pair.request.url.includes("bedrock-runtime")) {
   111→			const urlMatch = pair.request.url.match(/\/model\/([^\/]+)/);
   112→			if (urlMatch && urlMatch[1]) {
   113→				return this.normalizeModelName(urlMatch[1]);
   114→			}
   115→		}
   116→
   117→		// Try to get model from request body
   118→		if (pair.request.body && pair.request.body.model) {
   119→			return this.normalizeModelName(pair.request.body.model);
   120→		}
   121→
   122→		// Default fallback
   123→		return "unknown";
   124→	}
   125→
   126→	private normalizeModelName(modelName: string): string {
   127→		if (!modelName) return "unknown";
   128→
   129→		// Handle Bedrock model names
   130→		if (modelName.startsWith("us.anthropic.")) {
   131→			// Convert "us.anthropic.claude-3-5-sonnet-20241022-v1:0" to "claude-3-5-sonnet-20241022"
   132→			const match = modelName.match(/us\.anthropic\.([^:]+)/);
   133→			if (match && match[1]) {
   134→				return match[1];
   135→			}
   136→		}
   137→
   138→		// Return as-is for other formats
   139→		return modelName;
   140→	}
