   393→	private renderToolUseContent(toolUse: any): TemplateResult {
   394→		const toolName = toolUse.name;
   395→		const input = toolUse.input;
   396→
   397→		if (toolName === "TodoWrite" && input?.todos) {
   398→			const todos = input.todos;
   399→
   400→			return this.wrapInScrollable(
   401→				html`${todos.map((todo: any) => {
   402→					const statusClass =
   403→						todo.status === "completed"
   404→							? "line-through text-vs-text"
   405→							: todo.status === "in_progress"
   406→								? "text-green-400"
   407→								: "text-vs-muted";
   408→
   409→					return html`
   410→						<div class="overflow-hidden whitespace-nowrap text-ellipsis ${statusClass}">• ${todo.content}</div>
   411→					`;
   412→				})}`,
   413→				false,
   414→			);
   415→		}
   416→
   417→		if (toolName === "NotebookEdit" && input?.new_source) {
   418→			const content = input.new_source;
   419→
   420→			return this.wrapInScrollable(content);
   421→		}
   422→
   423→		if (toolName === "Write" && input?.content) {
   424→			const content = input.content;
   425→
   426→			return this.wrapInScrollable(content);
   427→		}
   428→
   429→		if (toolName === "MultiEdit" && input?.edits) {
   430→			const edits = input.edits;
   431→
   432→			return this.wrapInScrollable(
   433→				html`${edits.map((edit: any, index: number) => {
   434→					const oldStr = edit.old_string;
   435→					const newStr = edit.new_string;
   436→
   437→					const diffLines = this.renderDiff(oldStr, newStr);
   438→
   439→					return html`
   440→						<div class="mb-4">
   441→							<div class="text-vs-muted mb-2">Edit ${index + 1}:</div>
   442→							<div>${diffLines}</div>
   443→						</div>
   444→					`;
   445→				})}`,
   446→				false,
   447→			);
   448→		}
   449→
   450→		if (toolName === "Edit" && input?.old_string && input?.new_string) {
   451→			const oldStr = input.old_string;
   452→			const newStr = input.new_string;
   453→
   454→			const diffLines = this.renderDiff(oldStr, newStr);
   455→
   456→			return this.wrapInScrollable(html`${diffLines}`, false);
   457→		}
   458→
   459→		if (toolName === "WebFetch" && input?.url && input?.prompt) {
   460→			return this.wrapInScrollable(
   461→				html`
   462→					<div class="mb-3">
   463→						<div class="text-vs-muted mb-1">URL:</div>
   464→						<div class="text-vs-text">${input.url}</div>
   465→					</div>
   466→					<div>
   467→						<div class="text-vs-muted mb-1">Prompt:</div>
   468→						<div class="text-vs-text">${input.prompt}</div>
   469→					</div>
   470→				`,
   471→				false,
   472→			);
   473→		}
   474→
   475→		if (toolName === "WebSearch" && input?.query) {
   476→			const params = [];
   477→			params.push(html`
   478→				<div class="mb-3">
   479→					<div class="text-vs-muted mb-1">Query:</div>
   480→					<div class="text-vs-text">${input.query}</div>
   481→				</div>
   482→			`);
   483→
   484→			if (input?.allowed_domains) {
   485→				params.push(html`
   486→					<div class="mb-3">
   487→						<div class="text-vs-muted mb-1">Allowed Domains:</div>
   488→						<div class="text-vs-text">${input.allowed_domains.join(", ")}</div>
   489→					</div>
   490→				`);
   491→			}
   492→
   493→			if (input?.blocked_domains) {
   494→				params.push(html`
   495→					<div class="mb-3">
   496→						<div class="text-vs-muted mb-1">Blocked Domains:</div>
   497→						<div class="text-vs-text">${input.blocked_domains.join(", ")}</div>
   498→					</div>
   499→				`);
   500→			}
   501→
   502→			return this.wrapInScrollable(html`${params}`, false);
   503→		}
   504→
   505→		// Default: show JSON parameters
   506→		return this.wrapInScrollable(JSON.stringify(input, null, 2));
   507→	}
