    85→		}
    86→
    87→		if (Array.isArray(content)) {
    88→			return html`
    89→				${content.map((block) => {
    90→					if (block.type === "text") {
    91→						return this.formatStringContent(block.text);
    92→					} else if (block.type === "thinking") {
    93→						const thinkingBlock = block as any;
    94→						return html`
    95→							<div class="mt-4 mb-4">
    96→								<div class="text-gray-500 italic">
    97→									<em>Thinking</em>
