    99→								<div class="text-gray-400 mt-2 markdown-content">
   100→									${unsafeHTML(markdownToHtml(thinkingBlock.thinking || ""))}
   101→								</div>
   102→							</div>
   103→						`;
   104→					} else if (block.type === "tool_result") {
   105→						// Skip standalone tool_result blocks - they will be paired with tool_use
   106→						return html``;
   107→					} else if (block.type === "tool_use") {
   108→						const toolUse = block as any;
   109→						const toolResult = toolResults?.[toolUse.id];
   110→
   111→						if (block.name === "TodoWrite" || block.name === "Edit" || block.name === "MultiEdit") {
   112→							return this.renderToolContainer(block, toolResult);
   113→						}
   114→						if (block.name === "Write") {
   115→							const customContent = html`
   116→								<div class="bg-vs-bg-secondary p-4 text-vs-text hidden">
   117→									${this.renderToolUseContent(block)}
   118→								</div>
   119→								<div
   120→									class="bg-vs-bg-secondary mx-4 p-4 text-vs-text cursor-pointer hover:bg-vs-border transition-colors"
   121→									@click=${this.toggleWriteContent}
   122→								>
   123→									${this.renderWritePreview(block)}
   124→								</div>
   125→							`;
   126→							return html`
   127→								<div class="mt-4 mb-4">
   128→									<div class="text-vs-type px-4 break-all">${this.getToolDisplayName(block)}</div>
   129→									${customContent} ${toolResult ? this.renderToolResult(toolResult, block) : ""}
   130→								</div>
   131→							`;
   132→						}
   133→						return this.renderToolContainer(block, toolResult, {
   134→							isCollapsible: true,
   135→							isCollapsed: true,
   136→							isClickToExpand: true,
   137→						});
   138→					}
   139→					return html`<pre class="mb-4">${JSON.stringify(block, null, 2)}</pre>`;
   140→				})}
   141→			`;
   142→		}
   143→
   144→		return html`<pre>${JSON.stringify(content, null, 2)}</pre>`;
   145→	}
   146→
   147→	private formatStringContent(content: string): TemplateResult {
   148→		// Check for system reminder blocks (handling both raw and HTML-escaped delimiters)
   149→		const systemReminderRegexEscaped = /&lt;system-reminder&gt;([\s\S]*?)&lt;\/system-reminder&gt;/g;
   150→		const systemReminderRegexRaw = /<system-reminder>([\s\S]*?)<\/system-reminder>/g;
   151→		const systemReminders: string[] = [];
   152→		let match;
   153→
   154→		// Extract all system reminder blocks (escaped)
   155→		while ((match = systemReminderRegexEscaped.exec(content)) !== null) {
   156→			systemReminders.push(match[1].trim());
   157→		}
   158→
   159→		// Extract all system reminder blocks (raw)
   160→		while ((match = systemReminderRegexRaw.exec(content)) !== null) {
   161→			systemReminders.push(match[1].trim());
   162→		}
   163→
   164→		// Remove system reminder blocks from main content
   165→		let mainContent = content.replace(systemReminderRegexEscaped, "").replace(systemReminderRegexRaw, "").trim();
   166→
   167→		return html`
   168→			${mainContent ? html`<div class="mt-4 markdown-content">${unsafeHTML(markdownToHtml(mainContent))}</div>` : ""}
   169→			${systemReminders.length > 0
   170→				? this.renderCollapsibleSection(
   171→						"System Reminder",
   172→						html`<div class="text-vs-muted">
   173→							${systemReminders.map(
   174→								(reminder, index) => html`
   175→									<div class="mb-4">
   176→										${systemReminders.length > 1
   177→											? html`<div class="text-vs-function font-bold mb-2">Reminder ${index + 1}:</div>`
   178→											: ""}
   179→										<div class="markdown-content">${unsafeHTML(markdownToHtml(reminder))}</div>
   180→									</div>
   181→								`,
   182→							)}
   183→						</div>`,
   184→						{
   185→							titleClasses: "text-vs-muted",
   186→							containerClasses: "mt-4 mb-4",
   187→							count: systemReminders.length > 1 ? systemReminders.length : undefined,
   188→						},
   189→					)
   190→				: ""}
   191→		`;
   192→	}
