   194→	private formatSystem(system: string | TextBlockParam[] | undefined): string {
   195→		if (!system) return "";
   196→
   197→		if (typeof system === "string") {
   198→			return markdownToHtml(system);
   199→		}
   200→
   201→		if (Array.isArray(system)) {
   202→			const textContent = system
   203→				.map((block) => {
   204→					if (block.type === "text") {
   205→						return block.text;
   206→					}
   207→					return JSON.stringify(block, null, 2);
   208→				})
   209→				.join("\n");
   210→			return markdownToHtml(textContent);
   211→		}
   212→
   213→		return JSON.stringify(system, null, 2);
   214→	}
