   580→		}
   581→
   582→		const content = input.content;
   583→		const lines = content.split("\n");
   584→		const preview = lines.slice(0, 10);
   585→		const hasMore = lines.length > 10;
   586→
   587→		return html`
   588→			${this.wrapInScrollable(preview.join("\n"))}
   589→			${hasMore ? html`<div class="text-vs-muted">... ${lines.length - 10} more lines (click to expand)</div>` : ""}
   590→		`;
   591→	}
