   622→	private renderTools(tools: ToolUnion[]): TemplateResult {
   623→		return html`
   624→			${tools.map((tool) => {
   625→				if ("name" in tool && tool.name) {
   626→					const description = ("description" in tool && tool.description) || "No description";
   627→
   628→					return this.renderCollapsibleSection(
   629→						tool.name,
   630→						html`
   631→							<div class="text-vs-text ml-4 mb-3 markdown-content">
   632→								${unsafeHTML(markdownToHtml(description))}
   633→							</div>
   634→
   635→							${"input_schema" in tool && tool.input_schema && typeof tool.input_schema === "object"
   636→								? (() => {
   637→										const schema = tool.input_schema as any;
   638→										if (schema.properties) {
   639→											return html`
   640→												<div class="text-vs-muted mb-2">Parameters:</div>
   641→												${Object.entries(schema.properties).map(([paramName, paramDef]) => {
   642→													const def = paramDef as any;
