   716→								</div>
   717→							</div>
   718→						`,
   719→					)}
   720→
   721→				<!-- Assistant Response -->
   722→				<div class="mb-4">
   723→					<div class="font-bold uppercase text-vs-assistant">
   724→						<span>assistant</span>
   725→					</div>
