   593→	private renderDiff(oldStr: string, newStr: string): TemplateResult[] {
   594→		const diff = Diff.diffLines(oldStr, newStr);
   595→		const diffLines = [];
   596→
   597→		for (const part of diff) {
   598→			const lines = part.value.split("\n");
   599→			// Remove empty last line from split if it exists
   600→			if (lines[lines.length - 1] === "") {
   601→				lines.pop();
   602→			}
   603→
   604→			for (const line of lines) {
   605→				if (part.added) {
   606→					diffLines.push(html`<div class="bg-green-600/20"><pre class="text-vs-text m-0">+ ${line}</pre></div>`);
   607→				} else if (part.removed) {
   608→					diffLines.push(html`<div class="bg-red-600/20"><pre class="text-vs-text m-0">- ${line}</pre></div>`);
   609→				} else {
   610→					diffLines.push(html`<div><pre class="text-vs-text m-0">  ${line}</pre></div>`);
   611→				}
   612→			}
   613→		}
   614→
   615→		return diffLines;
   616→	}
