   587→    /**
   588→     * Process messages to pair tool_use with tool_result
   589→     */
   590→    private processToolResults(messages: MessageParam[]): EnhancedMessageParam[] {
   591→        const enhancedMessages: EnhancedMessageParam[] = [];
   592→        const pendingToolUses: Record<string, { messageIndex: number; toolIndex: number }> = {};
   593→
   594→        for (let i = 0; i < messages.length; i++) {
   595→            const message = messages[i];
   596→            const enhancedMessage: EnhancedMessageParam = { ...message, toolResults: {}, hide: false };
   597→
   598→            if (Array.isArray(message.content)) {
   599→                let hasOnlyToolResults = true;
   600→                let hasTextContent = false;
   601→
   602→                for (let j = 0; j < message.content.length; j++) {
   603→                    const block = message.content[j];
   604→
   605→                    if (block.type === "tool_use" && "id" in block) {
   606→                        const toolUse = block as ToolUseBlockType;
   607→                        pendingToolUses[toolUse.id] = { messageIndex: i, toolIndex: j };
   608→                        hasOnlyToolResults = false;
   609→                    } else if (block.type === "tool_result" && "tool_use_id" in block) {
   610→                        const toolResult = block as ToolResultBlockParam;
   611→                        const toolUseId = toolResult.tool_use_id;
   612→
   613→                        if (pendingToolUses[toolUseId]) {
   614→                            const { messageIndex } = pendingToolUses[toolUseId];
   615→                            if (!enhancedMessages[messageIndex]) {
   616→                                enhancedMessages[messageIndex] = { ...messages[messageIndex], toolResults: {}, hide: false };
   617→                            }
   618→                            enhancedMessages[messageIndex].toolResults![toolUseId] = toolResult;
   619→                            delete pendingToolUses[toolUseId];
   620→                        }
   621→                    } else if (block.type === "text") {
   622→                        hasTextContent = true;
   623→                        hasOnlyToolResults = false;
   624→                    } else {
   625→                        hasOnlyToolResults = false;
   626→                    }
   627→                }
   628→
   629→                if (hasOnlyToolResults && !hasTextContent) {
   630→                    enhancedMessage.hide = true;
   631→                }
   632→            }
   633→
   634→            enhancedMessages[i] = enhancedMessage;
   635→        }
   636→
   637→        return enhancedMessages;
   638→    }
