   147→	private formatStringContent(content: string): TemplateResult {
   148→		// Check for system reminder blocks (handling both raw and HTML-escaped delimiters)
   149→		const systemReminderRegexEscaped = /&lt;system-reminder&gt;([\s\S]*?)&lt;\/system-reminder&gt;/g;
   150→		const systemReminderRegexRaw = /<system-reminder>([\s\S]*?)<\/system-reminder>/g;
   151→		const systemReminders: string[] = [];
   152→		let match;
   153→
   154→		// Extract all system reminder blocks (escaped)
   155→		while ((match = systemReminderRegexEscaped.exec(content)) !== null) {
   156→			systemReminders.push(match[1].trim());
   157→		}
   158→
   159→		// Extract all system reminder blocks (raw)
   160→		while ((match = systemReminderRegexRaw.exec(content)) !== null) {
   161→			systemReminders.push(match[1].trim());
   162→		}
   163→
   164→		// Remove system reminder blocks from main content
   165→		let mainContent = content.replace(systemReminderRegexEscaped, "").replace(systemReminderRegexRaw, "").trim();
   166→
   167→		return html`
   168→			${mainContent ? html`<div class="mt-4 markdown-content">${unsafeHTML(markdownToHtml(mainContent))}</div>` : ""}
   169→			${systemReminders.length > 0
   170→				? this.renderCollapsibleSection(
   171→						"System Reminder",
   172→						html`<div class="text-vs-muted">
   173→							${systemReminders.map(
   174→								(reminder, index) => html`
   175→									<div class="mb-4">
   176→										${systemReminders.length > 1
   177→											? html`<div class="text-vs-function font-bold mb-2">Reminder ${index + 1}:</div>`
   178→											: ""}
   179→										<div class="markdown-content">${unsafeHTML(markdownToHtml(reminder))}</div>
   180→									</div>
   181→								`,
   182→							)}
   183→						</div>`,
   184→						{
