   422→
   423→		if (toolName === "Write" && input?.content) {
   424→			const content = input.content;
   425→
   426→			return this.wrapInScrollable(content);
   427→		}
   428→
   429→		if (toolName === "MultiEdit" && input?.edits) {
   430→			const edits = input.edits;
   431→
   432→			return this.wrapInScrollable(
   433→				html`${edits.map((edit: any, index: number) => {
   434→					const oldStr = edit.old_string;
   435→					const newStr = edit.new_string;
   436→
   437→					const diffLines = this.renderDiff(oldStr, newStr);
   438→
   439→					return html`
