   443→						</div>
   444→					`;
   445→				})}`,
   446→				false,
   447→			);
   448→		}
   449→
   450→		if (toolName === "Edit" && input?.old_string && input?.new_string) {
   451→			const oldStr = input.old_string;
   452→			const newStr = input.new_string;
   453→
   454→			const diffLines = this.renderDiff(oldStr, newStr);
   455→
   456→			return this.wrapInScrollable(html`${diffLines}`, false);
   457→		}
   458→
   459→		if (toolName === "WebFetch" && input?.url && input?.prompt) {
   460→			return this.wrapInScrollable(
   461→				html`
   462→					<div class="mb-3">
   463→						<div class="text-vs-muted mb-1">URL:</div>
   464→						<div class="text-vs-text">${input.url}</div>
   465→					</div>
   466→					<div>
   467→						<div class="text-vs-muted mb-1">Prompt:</div>
   468→						<div class="text-vs-text">${input.prompt}</div>
   469→					</div>
   470→				`,
   471→				false,
   472→			);
   473→		}
   474→
   475→		if (toolName === "WebSearch" && input?.query) {
   476→			const params = [];
   477→			params.push(html`
   478→				<div class="mb-3">
   479→					<div class="text-vs-muted mb-1">Query:</div>
   480→					<div class="text-vs-text">${input.query}</div>
   481→				</div>
   482→			`);
   483→
   484→			if (input?.allowed_domains) {
   485→				params.push(html`
   486→					<div class="mb-3">
   487→						<div class="text-vs-muted mb-1">Allowed Domains:</div>
   488→						<div class="text-vs-text">${input.allowed_domains.join(", ")}</div>
   489→					</div>
   490→				`);
   491→			}
   492→
   493→			if (input?.blocked_domains) {
   494→				params.push(html`
   495→					<div class="mb-3">
   496→						<div class="text-vs-muted mb-1">Blocked Domains:</div>
   497→						<div class="text-vs-text">${input.blocked_domains.join(", ")}</div>
   498→					</div>
   499→				`);
   500→			}
   501→
   502→			return this.wrapInScrollable(html`${params}`, false);
   503→		}
   504→
   505→		// Default: show JSON parameters
   506→		return this.wrapInScrollable(JSON.stringify(input, null, 2));
