    53→/**
    54→ * Shared conversation processing functionality for both frontend and backend
    55→ */
    56→export class SharedConversationProcessor {
    57→    /**
    58→     * Process raw JSONL pairs into ProcessedPairs
    59→     */
    60→    processRawPairs(rawPairs: RawPair[]): ProcessedPair[] {
    61→        if (!rawPairs || rawPairs.length === 0) {
    62→            return [];
    63→        }
    64→
    65→        const processedPairs: ProcessedPair[] = [];
    66→
    67→        for (let i = 0; i < rawPairs.length; i++) {
    68→            const pair = rawPairs[i];
    69→            if (!pair?.request || !pair?.response) {
    70→                continue;
    71→            }
    72→
    73→            try {
    74→                // Detect streaming
    75→                const isStreaming = !!pair.response.body_raw;
    76→                let response: Message;
    77→                let streamFormat: "standard" | "bedrock" | null = null;
    78→
    79→                if (pair.response.body_raw) {
    80→                    // Parse streaming response and detect format
    81→                    streamFormat = this.isBedrockResponse(pair.response.body_raw) ? "bedrock" : "standard";
    82→                    response = this.parseStreamingResponse(pair.response.body_raw);
    83→                } else if (pair.response.body) {
    84→                    response = pair.response.body as Message;
    85→                } else {
    86→                    continue;
    87→                }
    88→
    89→                // Extract model from request headers or URL
    90→                const model = this.extractModel(pair);
    91→
    92→                processedPairs.push({
    93→                    id: `${pair.request.timestamp || Date.now()}_${Math.random()}`,
    94→                    timestamp: new Date((pair.request.timestamp || Date.now()) * 1000).toISOString(),
    95→                    request: pair.request.body as MessageCreateParams,
    96→                    response,
    97→                    model,
    98→                    isStreaming,
    99→                    rawStreamData: pair.response.body_raw,
   100→                    streamFormat,
   101→                });
   102→            } catch (error) {
   103→                console.warn(`Failed to process raw pair at index ${i}:`, error);
   104→                // Continue processing other pairs
   105→            }
   106→        }
   107→
   108→        return processedPairs;
   109→    }
   110→
   111→    /**
   112→     * Detect if the response is from Bedrock by checking for binary event stream format
   113→     */
   114→    private isBedrockResponse(bodyRaw: string): boolean {
   115→        // Check for AWS EventStream format with binary headers and base64 encoded events
   116→        return bodyRaw.startsWith("\u0000\u0000");
   117→    }
   118→
   119→    /**
   120→     * Parse Bedrock binary event stream and extract the standard message events
   121→     */
   122→    private parseBedrockStreamingResponse(bodyRaw: string): Message {
   123→        if (!bodyRaw || bodyRaw.length === 0) {
   124→            throw new Error("Empty bodyRaw provided to parseBedrockStreamingResponse");
   125→        }
   126→
   127→        const events: RawMessageStreamEvent[] = [];
   128→        let bedrockMetrics: BedrockInvocationMetrics | null = null;
   129→
   130→        try {
   131→            // Extract JSON payloads from AWS EventStream format
   132→            // The format contains binary headers followed by JSON payloads
   133→            const jsonChunks = this.extractJsonChunksFromEventStream(bodyRaw);
   134→
   135→            for (const jsonChunk of jsonChunks) {
   136→                try {
   137→                    const eventPayload = JSON.parse(jsonChunk);
   138→
   139→                    // Check if this is an event with base64-encoded bytes
   140→                    if (eventPayload.bytes) {
   141→                        const base64Data = eventPayload.bytes;
   142→                        const decodedJson = this.decodeBase64ToUtf8(base64Data);
   143→                        const event = JSON.parse(decodedJson) as RawMessageStreamEvent;
   144→                        events.push(event);
   145→                    }
   146→                } catch (chunkError) {
   147→                    console.warn("Failed to parse JSON chunk:", jsonChunk, chunkError);
   148→                    // Continue with other chunks
   149→                }
   150→            }
   151→
   152→            // Extract Bedrock metrics from the last event if present
   153→            bedrockMetrics = this.extractBedrockMetrics(bodyRaw);
   154→        } catch (error) {
   155→            console.error("Failed to parse Bedrock streaming response:", error);
   156→            throw new Error(`Bedrock streaming response parsing failed: ${error}`);
   157→        }
   158→
   159→        return this.buildMessageFromEvents(events, bedrockMetrics);
   160→    }
   161→
   162→    /**
   163→     * Decode base64 string to UTF-8, compatible with both browser and Node.js environments
   164→     */
   165→    private decodeBase64ToUtf8(base64Data: string): string {
   166→        // Check if we're in a browser environment
   167→        if (typeof window !== "undefined" && typeof atob !== "undefined") {
   168→            // Browser environment - use atob()
   169→            return atob(base64Data);
   170→        } else if (typeof Buffer !== "undefined") {
   171→            // Node.js environment - use Buffer
   172→            return Buffer.from(base64Data, "base64").toString("utf-8");
   173→        } else {
   174→            // Fallback implementation for environments without either
   175→            throw new Error("Base64 decoding not supported in this environment");
   176→        }
   177→    }
   178→
   179→    /**
   180→     * Extract JSON chunks from AWS EventStream binary format
   181→     */
   182→    private extractJsonChunksFromEventStream(bodyRaw: string): string[] {
   183→        if (!bodyRaw || bodyRaw.length === 0) {
   184→            return [];
   185→        }
   186→
   187→        const jsonChunks: string[] = [];
   188→        const pattern = 'event{"bytes":';
   189→
   190→        let searchIndex = 0;
   191→
   192→        while (searchIndex < bodyRaw.length) {
   193→            // Find the next occurrence of the pattern
   194→            const patternIndex = bodyRaw.indexOf(pattern, searchIndex);
   195→            if (patternIndex === -1) {
   196→                break; // No more patterns found
   197→            }
   198→
   199→            // Start extracting JSON from the '{' after 'event'
   200→            const jsonStartIndex = patternIndex + 5; // Skip 'event' prefix
   201→            let braceCount = 0;
   202→            let jsonEndIndex = -1;
   203→
   204→            // Find the matching closing brace
   205→            for (let i = jsonStartIndex; i < bodyRaw.length; i++) {
   206→                const char = bodyRaw[i];
   207→
   208→                if (char === "{") {
   209→                    braceCount++;
   210→                } else if (char === "}") {
   211→                    braceCount--;
   212→                    if (braceCount === 0) {
   213→                        jsonEndIndex = i;
   214→                        break;
   215→                    }
   216→                }
   217→            }
   218→
   219→            // Extract the JSON chunk if we found a complete object
   220→            if (jsonEndIndex !== -1) {
   221→                const jsonChunk = bodyRaw.substring(jsonStartIndex, jsonEndIndex + 1);
   222→                jsonChunks.push(jsonChunk);
   223→                searchIndex = jsonEndIndex + 1;
   224→            } else {
   225→                // No matching brace found, move past this pattern
   226→                searchIndex = patternIndex + pattern.length;
   227→            }
   228→        }
   229→
   230→        return jsonChunks;
   231→    }
   232→
   233→    /**
   234→     * Extract Bedrock invocation metrics from the response
   235→     */
   236→    private extractBedrockMetrics(bodyRaw: string): BedrockInvocationMetrics | null {
   237→        try {
   238→            // Look for the amazon-bedrock-invocationMetrics in the last decoded event
   239→            const metricsMatch = bodyRaw.match(/"amazon-bedrock-invocationMetrics":\s*(\{[^}]+\})/);
   240→            if (metricsMatch && metricsMatch[1]) {
   241→                return JSON.parse(metricsMatch[1]) as BedrockInvocationMetrics;
   242→            }
   243→        } catch (e) {
   244→            // Skip invalid metrics
   245→        }
   246→        return null;
   247→    }
   248→
   249→    /**
   250→     * Parse streaming response from raw SSE data
   251→     */
   252→    private parseStreamingResponse(bodyRaw: string): Message {
   253→        if (this.isBedrockResponse(bodyRaw)) {
   254→            return this.parseBedrockStreamingResponse(bodyRaw);
   255→        } else {
   256→            return this.parseStandardStreamingResponse(bodyRaw);
   257→        }
   258→    }
   259→
   260→    /**
   261→     * Parse standard Anthropic API streaming response
   262→     */
   263→    private parseStandardStreamingResponse(bodyRaw: string): Message {
   264→        if (!bodyRaw || bodyRaw.length === 0) {
   265→            throw new Error("Empty bodyRaw provided to parseStandardStreamingResponse");
   266→        }
   267→
   268→        const lines = bodyRaw.split("\n");
   269→        const events: RawMessageStreamEvent[] = [];
   270→
   271→        for (const line of lines) {
   272→            if (!line.startsWith("data: ")) continue;
   273→
   274→            const data = line.substring(6).trim();
   275→            if (data === "[DONE]") break;
   276→
   277→            try {
   278→                const event = JSON.parse(data) as RawMessageStreamEvent;
   279→                events.push(event);
   280→            } catch (e) {
   281→                console.warn("Failed to parse SSE event:", data, e);
   282→                // Skip invalid JSON
   283→            }
   284→        }
   285→
   286→        return this.buildMessageFromEvents(events);
   287→    }
   288→
   289→    /**
   290→     * Build a Message object from a list of streaming events
   291→     */
   292→    private buildMessageFromEvents(
   293→        events: RawMessageStreamEvent[],
   294→        bedrockMetrics?: BedrockInvocationMetrics | null,
   295→    ): Message {
   296→        // Initialize with defaults
   297→        let message: Partial<Message> = {
   298→            id: "",
   299→            type: "message",
   300→            role: "assistant",
   301→            content: [],
   302→            model: "",
   303→            stop_reason: null,
   304→            stop_sequence: null,
   305→            usage: {
   306→                input_tokens: 0,
   307→                output_tokens: 0,
   308→                cache_creation_input_tokens: null,
   309→                cache_read_input_tokens: null,
   310→                server_tool_use: null,
   311→                service_tier: null,
   312→            },
   313→        };
   314→
   315→        // Track content blocks being built
   316→        const contentBlocks: ContentBlock[] = [];
   317→        let currentBlockIndex = -1;
   318→
   319→        for (const event of events) {
   320→            switch (event.type) {
   321→                case "message_start":
   322→                    // Initialize message with base structure
   323→                    message = { ...message, ...event.message };
   324→                    break;
   325→
   326→                case "content_block_start":
   327→                    // Start a new content block
   328→                    currentBlockIndex = event.index;
   329→                    contentBlocks[currentBlockIndex] = { ...event.content_block };
   330→                    break;
   331→
   332→                case "content_block_delta":
   333→                    // Update the current content block
   334→                    if (currentBlockIndex >= 0 && contentBlocks[currentBlockIndex]) {
   335→                        const block = contentBlocks[currentBlockIndex];
   336→                        const delta = event.delta;
   337→
   338→                        switch (delta.type) {
   339→                            case "text_delta":
   340→                                if (block.type === "text") {
   341→                                    (block as TextBlock).text = ((block as TextBlock).text || "") + delta.text;
   342→                                }
   343→                                break;
   344→
   345→                            case "input_json_delta":
   346→                                if (block.type === "tool_use") {
   347→                                    // Accumulate JSON string for tool_use blocks
   348→                                    const toolBlock = block as ToolUseBlockType;
   349→                                    if (typeof toolBlock.input === "string") {
   350→                                        toolBlock.input = toolBlock.input + delta.partial_json;
   351→                                    } else {
   352→                                        // Initialize as string if not already
   353→                                        (toolBlock.input as any) = delta.partial_json;
   354→                                    }
   355→                                }
   356→                                break;
   357→
   358→                            case "thinking_delta":
   359→                                if (block.type === "thinking") {
   360→                                    (block as ThinkingBlock).thinking =
   361→                                        ((block as ThinkingBlock).thinking || "") + delta.thinking;
   362→                                }
   363→                                break;
   364→
   365→                            case "signature_delta":
   366→                                if (block.type === "thinking") {
   367→                                    (block as ThinkingBlock).signature =
   368→                                        ((block as ThinkingBlock).signature || "") + delta.signature;
   369→                                }
   370→                                break;
   371→
   372→                            case "citations_delta":
   373→                                // Handle citations delta if needed
   374→                                break;
   375→                        }
   376→                    }
   377→                    break;
   378→
   379→                case "content_block_stop":
   380→                    // Finalize content block
   381→                    if (currentBlockIndex >= 0 && contentBlocks[currentBlockIndex]) {
   382→                        const block = contentBlocks[currentBlockIndex];
   383→                        // Parse JSON input if it's a tool_use block
   384→                        if (block.type === "tool_use") {
   385→                            const toolBlock = block as ToolUseBlockType;
   386→                            if (typeof toolBlock.input === "string") {
   387→                                try {
   388→                                    toolBlock.input = JSON.parse(toolBlock.input);
   389→                                } catch (e) {
   390→                                    // Keep as string if JSON parsing fails
   391→                                    console.warn("Failed to parse tool input JSON:", toolBlock.input);
   392→                                }
   393→                            }
   394→                        }
   395→                    }
   396→                    break;
   397→
   398→                case "message_delta":
   399→                    // Update message-level fields
   400→                    if (event.delta.stop_reason) {
   401→                        message.stop_reason = event.delta.stop_reason;
   402→                    }
   403→                    if (event.delta.stop_sequence) {
   404→                        message.stop_sequence = event.delta.stop_sequence;
   405→                    }
   406→                    if (event.usage) {
   407→                        // Preserve existing input_tokens if not provided in this delta
   408→                        // Input tokens are typically only sent once and shouldn't change
   409→                        const currentInputTokens = message.usage?.input_tokens ?? 0;
   410→
   411→                        message.usage = {
   412→                            input_tokens: event.usage.input_tokens ?? currentInputTokens,
   413→                            output_tokens: event.usage.output_tokens ?? message.usage?.output_tokens ?? 0,
   414→                            cache_creation_input_tokens:
   415→                                event.usage.cache_creation_input_tokens ?? message.usage?.cache_creation_input_tokens ?? null,
   416→                            cache_read_input_tokens:
   417→                                event.usage.cache_read_input_tokens ?? message.usage?.cache_read_input_tokens ?? null,
   418→                            server_tool_use: event.usage.server_tool_use ?? message.usage?.server_tool_use ?? null,
   419→                            service_tier: null, // MessageDeltaUsage doesn't have service_tier
   420→                        };
   421→                    }
   422→                    break;
   423→
   424→                case "message_stop":
   425→                    // Finalize message
   426→                    break;
   427→            }
   428→        }
   429→
   430→        // Set the final content blocks
   431→        message.content = contentBlocks.filter((block) => block != null);
   432→
   433→        // If we have bedrock metrics, merge them into usage
   434→        if (bedrockMetrics && message.usage) {
   435→            message.usage.input_tokens = bedrockMetrics.inputTokenCount;
   436→            message.usage.output_tokens = bedrockMetrics.outputTokenCount;
   437→        }
   438→
   439→        return message as Message;
   440→    }
   441→
   442→    /**
   443→     * Extract model name from the raw pair
   444→     */
   445→    private extractModel(pair: RawPair): string {
   446→        // Try to extract from Bedrock URL
   447→        if (pair.request?.url && pair.request.url.includes("bedrock-runtime")) {
   448→            const urlMatch = pair.request.url.match(/\/model\/([^\/]+)/);
   449→            if (urlMatch && urlMatch[1]) {
   450→                return this.normalizeModelName(urlMatch[1]);
   451→            }
   452→        }
   453→
   454→        // Try to get model from request body
   455→        if (pair.request?.body && typeof pair.request.body === "object" && "model" in pair.request.body) {
   456→            return this.normalizeModelName((pair.request.body as any).model);
   457→        }
   458→
   459→        // Try to get from response
   460→        if (pair.response?.body && typeof pair.response.body === "object" && "model" in pair.response.body) {
   461→            return this.normalizeModelName((pair.response.body as any).model);
   462→        }
   463→
   464→        // Default
   465→        return "unknown";
   466→    }
   467→
   468→    /**
   469→     * Normalize model names from different formats to a consistent display format
   470→     */
   471→    private normalizeModelName(modelName: string): string {
   472→        if (!modelName) return "unknown";
   473→
   474→        // Handle Bedrock model names
   475→        if (modelName.startsWith("us.anthropic.")) {
   476→            // Convert "us.anthropic.claude-3-5-sonnet-20241022-v1:0" to "claude-3-5-sonnet-20241022"
   477→            const match = modelName.match(/us\.anthropic\.([^:]+)/);
   478→            if (match && match[1]) {
   479→                return match[1];
   480→            }
   481→        }
   482→
   483→        // Return as-is for other formats
   484→        return modelName;
   485→    }
   486→
   487→    /**
   488→     * Group processed pairs into conversations
   489→     */
   490→    mergeConversations(
   491→        pairs: ProcessedPair[],
   492→        options: { includeShortConversations?: boolean } = {},
   493→    ): SimpleConversation[] {
   494→        if (!pairs || pairs.length === 0) return [];
   495→
   496→        // Group pairs by system instructions + model
   497→        const pairsBySystem = new Map<string, ProcessedPair[]>();
   498→
   499→        for (const pair of pairs) {
   500→            const system = pair.request.system;
   501→            const model = pair.model;
   502→            const systemKey = JSON.stringify({ system, model });
   503→
   504→            if (!pairsBySystem.has(systemKey)) {
   505→                pairsBySystem.set(systemKey, []);
   506→            }
   507→            pairsBySystem.get(systemKey)!.push(pair);
   508→        }
   509→
   510→        const allConversations: SimpleConversation[] = [];
   511→
   512→        for (const [, systemPairs] of pairsBySystem) {
   513→            const sortedPairs = [...systemPairs].sort(
   514→                (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   515→            );
   516→
   517→            // Group pairs by conversation thread
   518→            const conversationThreads = new Map<string, ProcessedPair[]>();
   519→
   520→            for (const pair of sortedPairs) {
   521→                const messages = pair.request.messages || [];
   522→                if (messages.length === 0) continue;
   523→
   524→                const firstUserMessage = messages[0];
   525→                const normalizedFirstMessage = this.normalizeMessageForGrouping(firstUserMessage);
   526→                const conversationKey = JSON.stringify({ firstMessage: normalizedFirstMessage });
   527→                const keyHash = this.hashString(conversationKey);
   528→
   529→                if (!conversationThreads.has(keyHash)) {
   530→                    conversationThreads.set(keyHash, []);
   531→                }
   532→                conversationThreads.get(keyHash)!.push(pair);
   533→            }
   534→
   535→            // For each conversation thread, keep the final pair
   536→            for (const [conversationKey, threadPairs] of conversationThreads) {
   537→                const sortedThreadPairs = [...threadPairs].sort(
   538→                    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   539→                );
   540→
   541→                const finalPair = sortedThreadPairs.reduce((longest, current) => {
   542→                    const currentMessages = current.request.messages || [];
   543→                    const longestMessages = longest.request.messages || [];
   544→                    return currentMessages.length > longestMessages.length ? current : longest;
   545→                });
   546→
   547→                const modelsUsed = new Set(sortedThreadPairs.map((pair) => pair.model));
   548→                const enhancedMessages = this.processToolResults(finalPair.request.messages || []);
   549→
   550→                const conversation: SimpleConversation = {
   551→                    id: this.hashString(conversationKey),
   552→                    models: modelsUsed,
   553→                    system: finalPair.request.system,
   554→                    messages: enhancedMessages,
   555→                    response: finalPair.response,
   556→                    allPairs: sortedThreadPairs,
   557→                    finalPair: finalPair,
   558→                    metadata: {
   559→                        startTime: sortedThreadPairs[0].timestamp,
   560→                        endTime: finalPair.timestamp,
   561→                        totalPairs: sortedThreadPairs.length,
   562→                        inputTokens: finalPair.response.usage?.input_tokens || 0,
   563→                        outputTokens: finalPair.response.usage?.output_tokens || 0,
   564→                        totalTokens:
   565→                            (finalPair.response.usage?.input_tokens || 0) + (finalPair.response.usage?.output_tokens || 0),
   566→                    },
   567→                };
   568→
   569→                allConversations.push(conversation);
   570→            }
   571→        }
   572→
   573→        // Apply compact conversation detection
   574→        const mergedConversations = this.detectAndMergeCompactConversations(allConversations);
   575→
   576→        // Filter out short conversations unless explicitly included
   577→        const filteredConversations = options.includeShortConversations
   578→            ? mergedConversations
   579→            : mergedConversations.filter((conv) => conv.messages.length > 2);
   580→
   581→        // Sort by start time
   582→        return filteredConversations.sort(
   583→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   584→        );
   585→    }
   586→
   587→    /**
   588→     * Process messages to pair tool_use with tool_result
   589→     */
   590→    private processToolResults(messages: MessageParam[]): EnhancedMessageParam[] {
   591→        const enhancedMessages: EnhancedMessageParam[] = [];
   592→        const pendingToolUses: Record<string, { messageIndex: number; toolIndex: number }> = {};
   593→
   594→        for (let i = 0; i < messages.length; i++) {
   595→            const message = messages[i];
   596→            const enhancedMessage: EnhancedMessageParam = { ...message, toolResults: {}, hide: false };
   597→
   598→            if (Array.isArray(message.content)) {
   599→                let hasOnlyToolResults = true;
   600→                let hasTextContent = false;
   601→
   602→                for (let j = 0; j < message.content.length; j++) {
   603→                    const block = message.content[j];
   604→
   605→                    if (block.type === "tool_use" && "id" in block) {
   606→                        const toolUse = block as ToolUseBlockType;
   607→                        pendingToolUses[toolUse.id] = { messageIndex: i, toolIndex: j };
   608→                        hasOnlyToolResults = false;
   609→                    } else if (block.type === "tool_result" && "tool_use_id" in block) {
   610→                        const toolResult = block as ToolResultBlockParam;
   611→                        const toolUseId = toolResult.tool_use_id;
   612→
   613→                        if (pendingToolUses[toolUseId]) {
   614→                            const { messageIndex } = pendingToolUses[toolUseId];
   615→                            if (!enhancedMessages[messageIndex]) {
   616→                                enhancedMessages[messageIndex] = { ...messages[messageIndex], toolResults: {}, hide: false };
   617→                            }
   618→                            enhancedMessages[messageIndex].toolResults![toolUseId] = toolResult;
   619→                            delete pendingToolUses[toolUseId];
   620→                        }
   621→                    } else if (block.type === "text") {
   622→                        hasTextContent = true;
   623→                        hasOnlyToolResults = false;
   624→                    } else {
   625→                        hasOnlyToolResults = false;
   626→                    }
   627→                }
   628→
   629→                if (hasOnlyToolResults && !hasTextContent) {
   630→                    enhancedMessage.hide = true;
   631→                }
   632→            }
   633→
   634→            enhancedMessages[i] = enhancedMessage;
   635→        }
   636→
   637→        return enhancedMessages;
   638→    }
   639→
   640→    /**
   641→     * Detect and merge compact conversations
   642→     */
   643→    private detectAndMergeCompactConversations(conversations: SimpleConversation[]): SimpleConversation[] {
   644→        if (conversations.length <= 1) return conversations;
   645→
   646→        const sortedConversations = [...conversations].sort(
   647→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   648→        );
   649→
   650→        const usedConversations = new Set<number>();
   651→        const mergedConversations: SimpleConversation[] = [];
   652→
   653→        for (let i = 0; i < sortedConversations.length; i++) {
   654→            const currentConv = sortedConversations[i];
   655→
   656→            if (usedConversations.has(i)) continue;
   657→
   658→            // Check if this is a compact conversation (1 pair with many messages)
   659→            if (currentConv.allPairs.length === 1 && currentConv.messages.length > 2) {
   660→                let originalConv: SimpleConversation | null = null;
   661→                let originalIndex = -1;
   662→
   663→                for (let j = 0; j < sortedConversations.length; j++) {
   664→                    if (j === i || usedConversations.has(j)) continue;
   665→
   666→                    const otherConv = sortedConversations[j];
   667→
   668→                    // Check if other conversation has exactly 2 fewer messages
   669→                    if (otherConv.messages.length === currentConv.messages.length - 2) {
   670→                        // Check if messages match (simplified check)
   671→                        let messagesMatch = true;
   672→                        for (let k = 1; k < otherConv.messages.length; k++) {
   673→                            if (!this.messagesRoughlyEqual(otherConv.messages[k], currentConv.messages[k])) {
   674→                                messagesMatch = false;
   675→                                break;
   676→                            }
   677→                        }
   678→
   679→                        if (messagesMatch) {
   680→                            originalConv = otherConv;
   681→                            originalIndex = j;
   682→                            break;
   683→                        }
   684→                    }
   685→                }
   686→
   687→                if (originalConv) {
   688→                    const mergedConv = this.mergeCompactConversation(originalConv, currentConv);
   689→                    mergedConversations.push(mergedConv);
   690→                    usedConversations.add(i);
   691→                    usedConversations.add(originalIndex);
   692→                } else {
   693→                    currentConv.compacted = true;
   694→                    mergedConversations.push(currentConv);
   695→                    usedConversations.add(i);
   696→                }
   697→            } else {
   698→                mergedConversations.push(currentConv);
   699→                usedConversations.add(i);
   700→            }
   701→        }
   702→
   703→        // Add remaining conversations
   704→        for (let i = 0; i < sortedConversations.length; i++) {
   705→            if (!usedConversations.has(i)) {
   706→                mergedConversations.push(sortedConversations[i]);
   707→            }
   708→        }
   709→
   710→        return mergedConversations.sort(
   711→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   712→        );
   713→    }
   714→
   715→    /**
   716→     * Merge a compact conversation with its original counterpart
   717→     */
   718→    private mergeCompactConversation(
   719→        originalConv: SimpleConversation,
   720→        compactConv: SimpleConversation,
   721→    ): SimpleConversation {
   722→        const originalMessages = originalConv.messages || [];
   723→        const compactMessages = compactConv.messages || [];
   724→
   725→        const mergedMessages = [...compactMessages];
   726→        if (originalMessages.length > 0 && mergedMessages.length > 0) {
   727→            mergedMessages[0] = originalMessages[0];
   728→        }
   729→
   730→        const allPairs = [...originalConv.allPairs, ...compactConv.allPairs].sort(
   731→            (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   732→        );
   733→
   734→        const allModels = new Set([...originalConv.models, ...compactConv.models]);
   735→        const startTime = allPairs[0].timestamp;
   736→        const endTime = allPairs[allPairs.length - 1].timestamp;
   737→
   738→        return {
   739→            id: compactConv.id,
   740→            models: allModels,
   741→            system: originalConv.system,
   742→            messages: mergedMessages,
   743→            response: compactConv.response,
   744→            allPairs: allPairs,
   745→            finalPair: compactConv.finalPair,
   746→            compacted: true,
   747→            metadata: {
   748→                startTime: startTime,
   749→                endTime: endTime,
   750→                totalPairs: allPairs.length,
   751→                inputTokens: (originalConv.metadata.inputTokens || 0) + (compactConv.metadata.inputTokens || 0),
   752→                outputTokens: (originalConv.metadata.outputTokens || 0) + (compactConv.metadata.outputTokens || 0),
   753→                totalTokens: (originalConv.metadata.totalTokens || 0) + (compactConv.metadata.totalTokens || 0),
   754→            },
   755→        };
   756→    }
   757→
   758→    /**
   759→     * Compare two messages to see if they're roughly equal
   760→     */
   761→    private messagesRoughlyEqual(msg1: MessageParam, msg2: MessageParam): boolean {
   762→        if (msg1.role !== msg2.role) return false;
   763→
   764→        const content1 = msg1.content;
   765→        const content2 = msg2.content;
   766→
   767→        if (typeof content1 !== typeof content2) return false;
   768→        if (Array.isArray(content1) !== Array.isArray(content2)) return false;
   769→
   770→        return true;
   771→    }
   772→
   773→    /**
   774→     * Normalize message for grouping (removes dynamic content)
   775→     */
   776→    private normalizeMessageForGrouping(message: MessageParam): MessageParam {
   777→        if (!message || !message.content) return message;
   778→
   779→        let normalizedContent: string | ContentBlockParam[];
   780→
   781→        if (Array.isArray(message.content)) {
   782→            normalizedContent = message.content.map((block) => {
   783→                if (block.type === "text" && "text" in block) {
   784→                    let text = block.text;
   785→                    text = text.replace(/Generated \d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/g, "Generated [TIMESTAMP]");
   786→                    text = text.replace(/The user opened the file [^\s]+ in the IDE\./g, "The user opened file in IDE.");
   787→                    text = text.replace(/<system-reminder>.*?<\/system-reminder>/gs, "[SYSTEM-REMINDER]");
   788→                    return { type: "text", text: text };
   789→                }
   790→                return block;
   791→            });
   792→        } else {
   793→            normalizedContent = message.content;
   794→        }
   795→
   796→        return {
   797→            role: message.role,
   798→            content: normalizedContent,
   799→        };
   800→    }
   801→
   802→    /**
   803→     * Generate hash string for conversation grouping
   804→     */
   805→    private hashString(str: string): string {
   806→        let hash = 0;
   807→        for (let i = 0; i < str.length; i++) {
   808→            const char = str.charCodeAt(i);
   809→            hash = (hash << 5) - hash + char;
   810→            hash = hash & hash;
   811→        }
   812→        return Math.abs(hash).toString();
   813→    }
   814→}
