   152→		const content = header.nextElementSibling as HTMLElement;
   153→		const toggle = header.querySelector("span:first-child") as HTMLElement;
   154→
   155→		if (content && toggle) {
   156→			const isHidden = content.classList.contains("hidden");
   157→			content.classList.toggle("hidden", !isHidden);
   158→			toggle.textContent = isHidden ? "[-]" : "[+]";
   159→		}
   160→	}
