     1→import { LitElement, html } from "lit";
     2→import { customElement, property } from "lit/decorators.js";
     3→import { ProcessedPair } from "../../../src/shared-conversation-processor";
     4→
     5→@customElement("json-view")
     6→export class JsonView extends LitElement {
     7→	@property({ type: Array }) processedPairs: ProcessedPair[] = [];
     8→
     9→	// Disable shadow DOM to use global CSS
    10→	createRenderRoot() {
    11→		return this;
    12→	}
    13→
    14→	render() {
    15→		if (this.processedPairs.length === 0) {
    16→			return html`<div class="text-vs-muted">No processed pairs found.</div>`;
    17→		}
    18→
    19→		return html`
    20→			<div>
    21→				${this.processedPairs.map(
    22→					(pair, index) => html`
    23→						<div class="mt-8 first:mt-0">
    24→							<!-- Pair Header -->
    25→							<div class="border border-vs-highlight p-4 mb-0">
    26→								<div class="text-vs-assistant font-bold">${pair.model}</div>
    27→								<div class="text-vs-muted">
    28→									Pair ${index + 1} • ${pair.isStreaming ? "streaming" : "non-streaming"} •
    29→									${new Date(pair.timestamp).toLocaleString()}
    30→								</div>
    31→							</div>
    32→
    33→							<!-- Request Section -->
    34→							<div class="px-4 mt-4">
    35→								<div class="mb-4">
    36→									<div
    37→										class="cursor-pointer text-vs-user font-bold hover:text-white transition-colors"
    38→										@click=${(e: Event) => this.toggleContent(e)}
    39→									>
    40→										<span class="mr-2">[+]</span>
    41→										<span>Request (MessageCreateParams)</span>
    42→									</div>
    43→									<div class="hidden mt-2">
    44→										<div class="bg-vs-bg-secondary p-4 text-vs-text overflow-x-auto">
    45→											<pre class="whitespace-pre text-vs-text m-0">${this.formatJson(pair.request)}</pre>
    46→										</div>
    47→									</div>
    48→								</div>
    49→
    50→								<!-- Response Section -->
    51→								<div class="mb-4">
    52→									<div
    53→										class="cursor-pointer text-vs-assistant font-bold hover:text-white transition-colors"
    54→										@click=${(e: Event) => this.toggleContent(e)}
    55→									>
    56→										<span class="mr-2">[+]</span>
    57→										<span>Response (Message)${pair.isStreaming ? " - Reconstructed from SSE" : ""}</span>
