    25→	private handleToggle(
    26→		e: Event,
    27→		options: {
    28→			type?: "content" | "write" | "custom";
    29→			targetSelector?: string;
    30→			toggleSelector?: string;
    31→			customHandler?: (element: HTMLElement, isHidden: boolean) => void;
    32→		} = {},
    33→	) {
    34→		const { type = "content", targetSelector, toggleSelector, customHandler } = options;
    35→		const currentElement = e.currentTarget as HTMLElement;
    36→
    37→		if (type === "write") {
    38→			const fullContent = currentElement.previousElementSibling as HTMLElement;
    39→			if (fullContent) {
    40→				const isExpanded = !fullContent.classList.contains("hidden");
    41→				if (isExpanded) {
    42→					fullContent.classList.add("hidden");
    43→					currentElement.classList.remove("hidden");
    44→				} else {
    45→					fullContent.classList.remove("hidden");
    46→					currentElement.classList.add("hidden");
    47→				}
    48→			}
    49→			return;
    50→		}
    51→
    52→		// Default content toggle behavior
    53→		const target = targetSelector
    54→			? (currentElement.querySelector(targetSelector) as HTMLElement)
    55→			: (currentElement.nextElementSibling as HTMLElement);
    56→		const toggle = toggleSelector
    57→			? (currentElement.querySelector(toggleSelector) as HTMLElement)
    58→			: (currentElement.querySelector("span:first-child") as HTMLElement);
    59→
    60→		if (target) {
    61→			const isHidden = target.classList.contains("hidden");
    62→
    63→			if (customHandler) {
    64→				customHandler(target, isHidden);
    65→			} else {
    66→				target.classList.toggle("hidden", !isHidden);
    67→				if (toggle) {
    68→					toggle.textContent = isHidden ? "[-]" : "[+]";
    69→				}
    70→			}
    71→		}
