   343→			case "Grep":
   344→				if (input?.pattern) {
   345→					const params = [this.unescapeHtml(input.pattern)];
   346→					if (input?.include) params.push(this.unescapeHtml(input.include));
   347→					if (input?.path) params.push(this.unescapeHtml(input.path));
