   633→							</div>
   634→
   635→							${"input_schema" in tool && tool.input_schema && typeof tool.input_schema === "object"
   636→								? (() => {
   637→										const schema = tool.input_schema as any;
   638→										if (schema.properties) {
   639→											return html`
   640→												<div class="text-vs-muted mb-2">Parameters:</div>
   641→												${Object.entries(schema.properties).map(([paramName, paramDef]) => {
   642→													const def = paramDef as any;
   643→													const required = schema.required?.includes(paramName) ? " (required)" : "";
   644→													const type = def.type ? ` [${def.type}]` : "";
   645→													const desc = def.description ? ` - ${def.description}` : "";
   646→													return html`
   647→														<div class="ml-4 mb-1">
   648→															<span class="text-vs-user">${paramName}</span>
   649→															<span class="text-vs-muted">${type}${required}${desc}</span>
   650→														</div>
   651→													`;
   652→												})}
   653→											`;
   654→										}
   655→										return html``;
   656→									})()
   657→								: html``}
   658→						`,
   659→						{
   660→							titleClasses: "text-vs-type font-bold",
   661→							containerClasses: "mb-4",
   662→							isExpanded: true,
   663→						},
   664→					);
   665→				}
   666→				return html`<pre class="mb-4">${JSON.stringify(tool, null, 2)}</pre>`;
   667→			})}
   668→		`;
   669→	}
