   289→    /**
   290→     * Build a Message object from a list of streaming events
   291→     */
   292→    private buildMessageFromEvents(
   293→        events: RawMessageStreamEvent[],
   294→        bedrockMetrics?: BedrockInvocationMetrics | null,
   295→    ): Message {
   296→        // Initialize with defaults
   297→        let message: Partial<Message> = {
   298→            id: "",
   299→            type: "message",
   300→            role: "assistant",
   301→            content: [],
   302→            model: "",
   303→            stop_reason: null,
   304→            stop_sequence: null,
   305→            usage: {
   306→                input_tokens: 0,
   307→                output_tokens: 0,
   308→                cache_creation_input_tokens: null,
   309→                cache_read_input_tokens: null,
   310→                server_tool_use: null,
   311→                service_tier: null,
   312→            },
   313→        };
   314→
   315→        // Track content blocks being built
   316→        const contentBlocks: ContentBlock[] = [];
   317→        let currentBlockIndex = -1;
   318→
   319→        for (const event of events) {
   320→            switch (event.type) {
   321→                case "message_start":
   322→                    // Initialize message with base structure
   323→                    message = { ...message, ...event.message };
   324→                    break;
   325→
   326→                case "content_block_start":
   327→                    // Start a new content block
   328→                    currentBlockIndex = event.index;
   329→                    contentBlocks[currentBlockIndex] = { ...event.content_block };
   330→                    break;
   331→
   332→                case "content_block_delta":
   333→                    // Update the current content block
   334→                    if (currentBlockIndex >= 0 && contentBlocks[currentBlockIndex]) {
   335→                        const block = contentBlocks[currentBlockIndex];
   336→                        const delta = event.delta;
   337→
   338→                        switch (delta.type) {
   339→                            case "text_delta":
   340→                                if (block.type === "text") {
   341→                                    (block as TextBlock).text = ((block as TextBlock).text || "") + delta.text;
   342→                                }
   343→                                break;
   344→
   345→                            case "input_json_delta":
   346→                                if (block.type === "tool_use") {
   347→                                    // Accumulate JSON string for tool_use blocks
   348→                                    const toolBlock = block as ToolUseBlockType;
   349→                                    if (typeof toolBlock.input === "string") {
   350→                                        toolBlock.input = toolBlock.input + delta.partial_json;
   351→                                    } else {
   352→                                        // Initialize as string if not already
   353→                                        (toolBlock.input as any) = delta.partial_json;
   354→                                    }
   355→                                }
   356→                                break;
   357→
   358→                            case "thinking_delta":
   359→                                if (block.type === "thinking") {
   360→                                    (block as ThinkingBlock).thinking =
   361→                                        ((block as ThinkingBlock).thinking || "") + delta.thinking;
   362→                                }
   363→                                break;
   364→
   365→                            case "signature_delta":
   366→                                if (block.type === "thinking") {
   367→                                    (block as ThinkingBlock).signature =
   368→                                        ((block as ThinkingBlock).signature || "") + delta.signature;
   369→                                }
   370→                                break;
   371→
   372→                            case "citations_delta":
   373→                                // Handle citations delta if needed
   374→                                break;
   375→                        }
   376→                    }
   377→                    break;
   378→
   379→                case "content_block_stop":
   380→                    // Finalize content block
   381→                    if (currentBlockIndex >= 0 && contentBlocks[currentBlockIndex]) {
   382→                        const block = contentBlocks[currentBlockIndex];
   383→                        // Parse JSON input if it's a tool_use block
   384→                        if (block.type === "tool_use") {
   385→                            const toolBlock = block as ToolUseBlockType;
   386→                            if (typeof toolBlock.input === "string") {
   387→                                try {
   388→                                    toolBlock.input = JSON.parse(toolBlock.input);
   389→                                } catch (e) {
   390→                                    // Keep as string if JSON parsing fails
   391→                                    console.warn("Failed to parse tool input JSON:", toolBlock.input);
   392→                                }
   393→                            }
   394→                        }
   395→                    }
   396→                    break;
   397→
   398→                case "message_delta":
   399→                    // Update message-level fields
   400→                    if (event.delta.stop_reason) {
   401→                        message.stop_reason = event.delta.stop_reason;
   402→                    }
   403→                    if (event.delta.stop_sequence) {
   404→                        message.stop_sequence = event.delta.stop_sequence;
   405→                    }
   406→                    if (event.usage) {
   407→                        // Preserve existing input_tokens if not provided in this delta
   408→                        // Input tokens are typically only sent once and shouldn't change
   409→                        const currentInputTokens = message.usage?.input_tokens ?? 0;
   410→
   411→                        message.usage = {
   412→                            input_tokens: event.usage.input_tokens ?? currentInputTokens,
   413→                            output_tokens: event.usage.output_tokens ?? message.usage?.output_tokens ?? 0,
   414→                            cache_creation_input_tokens:
   415→                                event.usage.cache_creation_input_tokens ?? message.usage?.cache_creation_input_tokens ?? null,
   416→                            cache_read_input_tokens:
   417→                                event.usage.cache_read_input_tokens ?? message.usage?.cache_read_input_tokens ?? null,
   418→                            server_tool_use: event.usage.server_tool_use ?? message.usage?.server_tool_use ?? null,
   419→                            service_tier: null, // MessageDeltaUsage doesn't have service_tier
   420→                        };
   421→                    }
   422→                    break;
   423→
   424→                case "message_stop":
   425→                    // Finalize message
   426→                    break;
   427→            }
   428→        }
   429→
   430→        // Set the final content blocks
   431→        message.content = contentBlocks.filter((block) => block != null);
   432→
   433→        // If we have bedrock metrics, merge them into usage
   434→        if (bedrockMetrics && message.usage) {
   435→            message.usage.input_tokens = bedrockMetrics.inputTokenCount;
   436→            message.usage.output_tokens = bedrockMetrics.outputTokenCount;
   437→        }
   438→
   439→        return message as Message;
   440→    }
