   126→	private normalizeModelName(modelName: string): string {
   127→		if (!modelName) return "unknown";
   128→
   129→		// Handle Bedrock model names
   130→		if (modelName.startsWith("us.anthropic.")) {
   131→			// Convert "us.anthropic.claude-3-5-sonnet-20241022-v1:0" to "claude-3-5-sonnet-20241022"
   132→			const match = modelName.match(/us\.anthropic\.([^:]+)/);
   133→			if (match && match[1]) {
   134→				return match[1];
   135→			}
   136→		}
   137→
   138→		// Return as-is for other formats
   139→		return modelName;
   140→	}
