   325→	private getToolDisplayName(toolUse: any, toolResult?: any): TemplateResult {
   326→		const toolName = toolUse.name;
   327→		const input = toolUse.input;
   328→
   329→		switch (toolName) {
   330→			case "Read":
   331→				return this.formatSingleParam(toolName, input?.file_path);
   332→			case "Bash":
   333→				return this.formatSingleParam(toolName, input?.command);
   334→			case "Write":
   335→				return this.formatSingleParam(toolName, input?.file_path);
   336→			case "Glob":
   337→				if (input?.pattern) {
   338→					const params = [this.unescapeHtml(input.pattern)];
   339→					if (input?.path) params.push(this.unescapeHtml(input.path));
   340→					return this.formatMultiParam(toolName, params);
   341→				}
   342→				return html`${toolName}`;
   343→			case "Grep":
   344→				if (input?.pattern) {
   345→					const params = [this.unescapeHtml(input.pattern)];
   346→					if (input?.include) params.push(this.unescapeHtml(input.include));
   347→					if (input?.path) params.push(this.unescapeHtml(input.path));
   348→					return this.formatMultiParam(toolName, params);
   349→				}
   350→				return html`${toolName}`;
   351→			case "LS":
   352→				if (input?.path) {
   353→					const params = [this.unescapeHtml(input.path)];
   354→					if (input?.ignore) {
   355→						const ignoreStr = input.ignore.map((p: string) => this.unescapeHtml(p)).join(", ");
   356→						params.push(`ignore: ${ignoreStr}`);
   357→					}
   358→					return this.formatMultiParam(toolName, params);
   359→				}
   360→				return html`${toolName}`;
   361→			case "Edit":
   362→				return input?.file_path
   363→					? this.formatSingleParam(toolName, this.unescapeHtml(input.file_path).split("/").pop())
   364→					: html`${toolName}`;
   365→			case "MultiEdit":
   366→				if (input?.file_path) {
   367→					const fileName = this.unescapeHtml(input.file_path).split("/").pop() || input.file_path;
   368→					const editCount = input?.edits ? input.edits.length : 0;
   369→					return this.formatMultiParam(toolName, [fileName, `${editCount} edits`]);
   370→				}
   371→				return html`${toolName}`;
   372→			case "NotebookRead":
   373→				return input?.notebook_path
   374→					? this.formatSingleParam(toolName, this.unescapeHtml(input.notebook_path).split("/").pop())
   375→					: html`${toolName}`;
   376→			case "NotebookEdit":
   377→				if (input?.notebook_path && input?.cell_number !== undefined) {
   378→					const fileName = this.unescapeHtml(input.notebook_path).split("/").pop();
   379→					const cellNum = input.cell_number;
   380→					const mode = input?.edit_mode || "replace";
   381→					return this.formatMultiParam(toolName, [fileName, `cell ${cellNum}`, mode]);
   382→				}
   383→				return html`${toolName}`;
   384→			case "WebFetch":
