    53→/**
    54→ * Shared conversation processing functionality for both frontend and backend
    55→ */
    56→export class SharedConversationProcessor {
    57→    /**
    58→     * Process raw JSONL pairs into ProcessedPairs
    59→     */
    60→    processRawPairs(rawPairs: RawPair[]): ProcessedPair[] {
    61→        if (!rawPairs || rawPairs.length === 0) {
    62→            return [];
    63→        }
    64→
    65→        const processedPairs: ProcessedPair[] = [];
    66→
    67→        for (let i = 0; i < rawPairs.length; i++) {
    68→            const pair = rawPairs[i];
    69→            if (!pair?.request || !pair?.response) {
    70→                continue;
    71→            }
    72→
    73→            try {
    74→                // Detect streaming
    75→                const isStreaming = !!pair.response.body_raw;
    76→                let response: Message;
    77→                let streamFormat: "standard" | "bedrock" | null = null;
    78→
    79→                if (pair.response.body_raw) {
    80→                    // Parse streaming response and detect format
    81→                    streamFormat = this.isBedrockResponse(pair.response.body_raw) ? "bedrock" : "standard";
    82→                    response = this.parseStreamingResponse(pair.response.body_raw);
    83→                } else if (pair.response.body) {
    84→                    response = pair.response.body as Message;
    85→                } else {
    86→                    continue;
    87→                }
    88→
    89→                // Extract model from request headers or URL
    90→                const model = this.extractModel(pair);
    91→
    92→                processedPairs.push({
    93→                    id: `${pair.request.timestamp || Date.now()}_${Math.random()}`,
    94→                    timestamp: new Date((pair.request.timestamp || Date.now()) * 1000).toISOString(),
    95→                    request: pair.request.body as MessageCreateParams,
    96→                    response,
    97→                    model,
    98→                    isStreaming,
    99→                    rawStreamData: pair.response.body_raw,
   100→                    streamFormat,
   101→                });
   102→            } catch (error) {
   103→                console.warn(`Failed to process raw pair at index ${i}:`, error);
   104→                // Continue processing other pairs
   105→            }
   106→        }
   107→
   108→        return processedPairs;
   109→    }
   110→
   111→    /**
   112→     * Detect if the response is from Bedrock by checking for binary event stream format
   113→     */
   114→    private isBedrockResponse(bodyRaw: string): boolean {
   115→        // Check for AWS EventStream format with binary headers and base64 encoded events
   116→        return bodyRaw.startsWith("\u0000\u0000");
   117→    }
   118→
   119→    /**
   120→     * Parse Bedrock binary event stream and extract the standard message events
   121→     */
   122→    private parseBedrockStreamingResponse(bodyRaw: string): Message {
   123→        if (!bodyRaw || bodyRaw.length === 0) {
   124→            throw new Error("Empty bodyRaw provided to parseBedrockStreamingResponse");
   125→        }
   126→
   127→        const events: RawMessageStreamEvent[] = [];
   128→        let bedrockMetrics: BedrockInvocationMetrics | null = null;
   129→
   130→        try {
   131→            // Extract JSON payloads from AWS EventStream format
   132→            // The format contains binary headers followed by JSON payloads
   133→            const jsonChunks = this.extractJsonChunksFromEventStream(bodyRaw);
   134→
   135→            for (const jsonChunk of jsonChunks) {
   136→                try {
   137→                    const eventPayload = JSON.parse(jsonChunk);
   138→
   139→                    // Check if this is an event with base64-encoded bytes
   140→                    if (eventPayload.bytes) {
   141→                        const base64Data = eventPayload.bytes;
   142→                        const decodedJson = this.decodeBase64ToUtf8(base64Data);
   143→                        const event = JSON.parse(decodedJson) as RawMessageStreamEvent;
   144→                        events.push(event);
   145→                    }
   146→                } catch (chunkError) {
   147→                    console.warn("Failed to parse JSON chunk:", jsonChunk, chunkError);
   148→                    // Continue with other chunks
   149→                }
   150→            }
   151→
   152→            // Extract Bedrock metrics from the last event if present
   153→            bedrockMetrics = this.extractBedrockMetrics(bodyRaw);
   154→        } catch (error) {
   155→            console.error("Failed to parse Bedrock streaming response:", error);
   156→            throw new Error(`Bedrock streaming response parsing failed: ${error}`);
   157→        }
   158→
   159→        return this.buildMessageFromEvents(events, bedrockMetrics);
   160→    }
   161→
   162→    /**
   163→     * Decode base64 string to UTF-8, compatible with both browser and Node.js environments
   164→     */
   165→    private decodeBase64ToUtf8(base64Data: string): string {
   166→        // Check if we're in a browser environment
   167→        if (typeof window !== "undefined" && typeof atob !== "undefined") {
   168→            // Browser environment - use atob()
   169→            return atob(base64Data);
   170→        } else if (typeof Buffer !== "undefined") {
   171→            // Node.js environment - use Buffer
   172→            return Buffer.from(base64Data, "base64").toString("utf-8");
   173→        } else {
   174→            // Fallback implementation for environments without either
   175→            throw new Error("Base64 decoding not supported in this environment");
   176→        }
   177→    }
   178→
   179→    /**
   180→     * Extract JSON chunks from AWS EventStream binary format
   181→     */
   182→    private extractJsonChunksFromEventStream(bodyRaw: string): string[] {
   183→        if (!bodyRaw || bodyRaw.length === 0) {
   184→            return [];
   185→        }
   186→
   187→        const jsonChunks: string[] = [];
   188→        const pattern = 'event{"bytes":';
   189→
   190→        let searchIndex = 0;
   191→
   192→        while (searchIndex < bodyRaw.length) {
   193→            // Find the next occurrence of the pattern
   194→            const patternIndex = bodyRaw.indexOf(pattern, searchIndex);
   195→            if (patternIndex === -1) {
   196→                break; // No more patterns found
   197→            }
   198→
   199→            // Start extracting JSON from the '{' after 'event'
   200→            const jsonStartIndex = patternIndex + 5; // Skip 'event' prefix
   201→            let braceCount = 0;
   202→            let jsonEndIndex = -1;
   203→
   204→            // Find the matching closing brace
   205→            for (let i = jsonStartIndex; i < bodyRaw.length; i++) {
   206→                const char = bodyRaw[i];
   207→
   208→                if (char === "{") {
   209→                    braceCount++;
   210→                } else if (char === "}") {
   211→                    braceCount--;
   212→                    if (braceCount === 0) {
   213→                        jsonEndIndex = i;
   214→                        break;
   215→                    }
   216→                }
   217→            }
   218→
   219→            // Extract the JSON chunk if we found a complete object
   220→            if (jsonEndIndex !== -1) {
   221→                const jsonChunk = bodyRaw.substring(jsonStartIndex, jsonEndIndex + 1);
   222→                jsonChunks.push(jsonChunk);
   223→                searchIndex = jsonEndIndex + 1;
   224→            } else {
   225→                // No matching brace found, move past this pattern
   226→                searchIndex = patternIndex + pattern.length;
   227→            }
   228→        }
   229→
   230→        return jsonChunks;
   231→    }
   232→
   233→    /**
   234→     * Extract Bedrock invocation metrics from the response
   235→     */
   236→    private extractBedrockMetrics(bodyRaw: string): BedrockInvocationMetrics | null {
   237→        try {
   238→            // Look for the amazon-bedrock-invocationMetrics in the last decoded event
   239→            const metricsMatch = bodyRaw.match(/"amazon-bedrock-invocationMetrics":\s*(\{[^}]+\})/);
   240→            if (metricsMatch && metricsMatch[1]) {
   241→                return JSON.parse(metricsMatch[1]) as BedrockInvocationMetrics;
   242→            }
   243→        } catch (e) {
   244→            // Skip invalid metrics
   245→        }
   246→        return null;
   247→    }
